import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import api from '../api/axios';
import { Container, Form, Button, Alert, Row, Col } from 'react-bootstrap';

const AdminPanel = () => {
  const navigate = useNavigate();
  const [classes, setClasses] = useState([]);
  const [positions, setPositions] = useState([]);
  const [studentForm, setStudentForm] = useState({
    last_name: '',
    first_name: '',
    middle_name: '',
    class_id: '',
    email: ''
  });
  const [teacherForm, setTeacherForm] = useState({
    last_name: '',
    first_name: '',
    middle_name: '',
    position_ids: [], // массив выбранных должностей
    email: ''
  });
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchClasses();
    fetchPositions();
  }, []);

  const fetchClasses = async () => {
    try {
      const res = await api.get('/director/classes');
      setClasses(res.data);
    } catch (err) {
      console.error('Ошибка загрузки классов:', err);
    }
  };

  const fetchPositions = async () => {
    try {
      const res = await api.get('/director/positions');      
      setPositions(res.data);
    } catch (err) {
      console.error('Ошибка загрузки должностей:', err);
    }
  };

  const handleStudentChange = (e) => {
    setStudentForm({ ...studentForm, [e.target.name]: e.target.value });
  };

  const handleTeacherChange = (e) => {
    const { name, value, options } = e.target;
    if (name === 'position_ids') {
      const selected = [];
      for (let option of options) {
        if (option.selected) {
          selected.push(parseInt(option.value));
        }
      }
      setTeacherForm({ ...teacherForm, position_ids: selected });
    } else {
      setTeacherForm({ ...teacherForm, [name]: value });
    }
  };

  const createStudent = async (e) => {
    e.preventDefault();
    setError('');
    setResult(null);
    try {
      const res = await api.post('/director/student', studentForm);
      setResult({ type: 'Ученик', ...res.data });
      setStudentForm({ last_name: '', first_name: '', middle_name: '', class_id: '', email: '' });
    } catch (err) {
      console.error('Ошибка:', err.response?.data);
      if (err.response?.data?.error === 'EMAIL_EXISTS') {
        setError('❌ Этот email уже используется. Пожалуйста, используйте другой email.');
      } else if (err.response?.data?.error === 'LOGIN_EXISTS') {
        setError('❌ Этот логин уже занят. Попробуйте снова.');
      } else {
        setError(err.response?.data?.error || 'Ошибка создания ученика');
      }
    }
  };

  const createTeacher = async (e) => {
    e.preventDefault();
    setError('');
    setResult(null);
    try {
      const res = await api.post('/director/teacher', teacherForm);
      setResult({ type: 'Учитель', ...res.data });
      setTeacherForm({ last_name: '', first_name: '', middle_name: '', position_ids: [], email: '' });
    } catch (err) {
      console.error('Ошибка:', err.response?.data);
      if (err.response?.data?.error === 'EMAIL_EXISTS') {
        setError('❌ Этот email уже используется. Пожалуйста, используйте другой email.');
      } else if (err.response?.data?.error === 'LOGIN_EXISTS') {
        setError('❌ Этот логин уже занят. Попробуйте снова.');
      } else {
        setError(err.response?.data?.error || 'Ошибка создания учителя');
      }
    }
  };

  return (
    <Container className="mt-4">
      <h3>Админ-панель (Директор)</h3>
      
      <div className="mb-3">
        <Link to="/classes" className="btn btn-info me-2">
          Управление классами
        </Link>
      </div>
      
      {error && <Alert variant="danger">{error}</Alert>}
      {result && (
        <Alert variant="success">
          <strong>{result.type} создан(а)!</strong><br />
          Логин: <code>{result.login}</code><br />
          Пароль: <code>{result.password}</code><br />
          (Сообщите эти данные пользователю)
        </Alert>
      )}

      <Row>
        <Col md={6}>
          <h5>Создать ученика</h5>
          <Form onSubmit={createStudent}>
            <Form.Group className="mb-2">
              <Form.Control
                name="last_name"
                placeholder="Фамилия"
                value={studentForm.last_name}
                onChange={handleStudentChange}
                required
              />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control
                name="first_name"
                placeholder="Имя"
                value={studentForm.first_name}
                onChange={handleStudentChange}
                required
              />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control
                name="middle_name"
                placeholder="Отчество"
                value={studentForm.middle_name}
                onChange={handleStudentChange}
              />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Select
                name="class_id"
                value={studentForm.class_id}
                onChange={handleStudentChange}
                required
              >
                <option value="">Выберите класс</option>
                {classes.map(cls => (
                  <option key={cls.id} value={cls.id}>
                    {cls.grade} класс
                  </option>
                ))}
              </Form.Select>
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control
                name="email"
                placeholder="Email (необязательно)"
                value={studentForm.email}
                onChange={handleStudentChange}
              />
            </Form.Group>
            <Button type="submit" variant="success">Создать ученика</Button>
          </Form>
        </Col>

        <Col md={6}>
          <h5>Создать учителя</h5>
          <Form onSubmit={createTeacher}>
            <Form.Group className="mb-2">
              <Form.Control
                name="last_name"
                placeholder="Фамилия"
                value={teacherForm.last_name}
                onChange={handleTeacherChange}
                required
              />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control
                name="first_name"
                placeholder="Имя"
                value={teacherForm.first_name}
                onChange={handleTeacherChange}
                required
              />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control
                name="middle_name"
                placeholder="Отчество"
                value={teacherForm.middle_name}
                onChange={handleTeacherChange}
              />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Должности (множественный выбор)</Form.Label>
              <Form.Select
                name="position_ids"
                value={teacherForm.position_ids}
                onChange={handleTeacherChange}
                multiple
                style={{ height: '150px' }}
                required
              >
                {positions.map(p => (
                  <option key={p.id} value={p.id}>
                    {p.name}
                  </option>
                ))}
              </Form.Select>
              <Form.Text className="text-muted">
                Удерживайте Ctrl (Windows) или Cmd (Mac) для выбора нескольких должностей
              </Form.Text>
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control
                name="email"
                placeholder="Email (необязательно)"
                value={teacherForm.email}
                onChange={handleTeacherChange}
              />
            </Form.Group>
            <Button type="submit" variant="primary">Создать учителя</Button>
          </Form>
        </Col>
      </Row>
    </Container>
  );
};

export default AdminPanel;
